-- Source: FED_SEC_13F_FILERS (344109 rows)
-- Generated by scripts/gen_mart_models.py
-- Fixed 2026-09-20: DATEDENIEDEXPIRED was a bare try_to_date() -- live-checked
-- clean today (0 of 1,581 filled rows misparsed; format is 'DD-MON-YYYY', which
-- Snowflake's auto-detect already reads correctly) but unguarded against a
-- future bad load. Now goes through stg_date(col) (auto) like every other
-- guarded date in this project. No staging model exists yet for this landing
-- table (checked models/staging/ -- only fed_sec_13f_positions and
-- fed_sec_13f_securities_list exist, both a different source table), so this
-- stays on source() with just the one cast wrapped.

with source as (
    select * from {{ source('ripple_raw', 'FED_SEC_13F_FILERS') }}
)

select
    ACCESSION_NUMBER as accession_number,
    REPORTCALENDARORQUARTER as reportcalendarorquarter,
    ISAMENDMENT as isamendment,
    AMENDMENTNO as amendmentno,
    AMENDMENTTYPE as amendmenttype,
    nullif(trim(CONFDENIEDEXPIRED), '') as confdeniedexpired,
    {{ stg_date('DATEDENIEDEXPIRED') }} as datedeniedexpired,
    DATEREPORTED as datereported,
    REASONFORNONCONFIDENTIALITY as reasonfornonconfidentiality,
    FILINGMANAGER_NAME as filingmanager_name,
    FILINGMANAGER_STREET1 as filingmanager_street1,
    FILINGMANAGER_STREET2 as filingmanager_street2,
    FILINGMANAGER_CITY as filingmanager_city,
    FILINGMANAGER_STATEORCOUNTRY as filingmanager_stateorcountry,
    FILINGMANAGER_ZIPCODE as filingmanager_zipcode,
    REPORTTYPE as reporttype,
    FORM13FFILENUMBER as form13_ffilenumber,
    CRDNUMBER as crdnumber,
    SECFILENUMBER as secfilenumber,
    PROVIDEINFOFORINSTRUCTION5 as provideinfoforinstruction5,
    ADDITIONALINFORMATION as additionalinformation,
    _SRC_FILE as src_file
from source
